function abs(rel) {
  return path.join(ROOT, rel);
}

function fail(message) {
  console.error("❌ " + message);
  process.exit(1);
}

if (!fs.existsSync(abs("package.json"))) {
  fail(
    "Ejecutá este parche dentro de alumni-web."
  );
}

for (const [rel, content] of Object.entries(FILES)) {
  const target = abs(rel);

  fs.mkdirSync(
    path.dirname(target),
    { recursive: true }
  );

  if (fs.existsSync(target)) {
    const current =
      fs.readFileSync(
        target,
        "utf8"
      );

    if (
      current.includes(MARKER)
    ) {
      console.log(
        `↪ ${rel}: ya aplicado`
      );
      continue;
    }

    const backup =
      target +
      ".before-admin-control-center-2.0.bak";

    if (
      !fs.existsSync(backup)
    ) {
      fs.writeFileSync(
        backup,
        current,
        "utf8"
      );
    }
  }

  fs.writeFileSync(
    target,
    content,
    "utf8"
  );

  console.log(
    `✅ ${rel}`
  );
}

